"""Benchmark the RAG pipeline against a synthetic QA testset generated by RAGAS.

Unlike the small hand-curated set in `dataset.py`, this generates its own questions (and
reference answers) straight from the indexed fiscal-code chunks, then scores our RAG
pipeline's answers against them with RAGAS's Faithfulness, Context Precision, Context
Recall and Answer Relevancy metrics. Every step here makes real LLM calls (generation +
4 metrics per sample), so this is a heavier/optional benchmark - not part of the default
`evaluate.py` run.
"""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from config import EMBEDDING_MODEL_NAME, MODEL_NAME, VECTOR_DB_DIR
from ingestion.embed import SentenceTransformerEmbeddings
from ingestion.vectorstore import load_vectorstore
from rag.llm import get_llm
from rag.rag import answer_question

METRIC_NAMES = ("faithfulness", "context_precision", "context_recall", "answer_relevancy")


def _load_indexed_chunks(store_name: str = VECTOR_DB_DIR):
    """Pull the already-ingested chunk texts back out of Chroma as LangChain Documents, so
    the RAGAS testset generator can synthesize questions from real indexed content without
    re-parsing the source HTML."""
    from langchain_core.documents import Document

    store = load_vectorstore(store_name)
    raw = store._collection.get(include=["documents", "metadatas"])
    return [
        Document(page_content=text, metadata=meta or {})
        for text, meta in zip(raw["documents"], raw["metadatas"])
    ]


def _build_testset_generator():
    from ragas.testset import TestsetGenerator

    return TestsetGenerator.from_langchain(llm=get_llm(), embedding_model=SentenceTransformerEmbeddings())


def generate_testset(store_name: str = VECTOR_DB_DIR, testset_size: int = 5):
    """Generate a synthetic QA testset from the indexed fiscal code chunks using RAGAS.

    @return a pandas DataFrame with (at least) "user_input" and "reference" columns
    """
    documents = _load_indexed_chunks(store_name)
    generator = _build_testset_generator()
    testset = generator.generate_with_chunks(documents, testset_size=testset_size)
    return testset.to_pandas()


def _build_ragas_metrics():
    from openai import OpenAI
    from ragas.embeddings import HuggingFaceEmbeddings
    from ragas.llms import llm_factory
    from ragas.metrics.collections import AnswerRelevancy, ContextPrecision, ContextRecall, Faithfulness

    from config import API_KEY

    judge = llm_factory(MODEL_NAME, provider="openai", client=OpenAI(api_key=API_KEY))
    embeddings = HuggingFaceEmbeddings(model=EMBEDDING_MODEL_NAME)

    return {
        "faithfulness": Faithfulness(llm=judge),
        "context_precision": ContextPrecision(llm=judge),
        "context_recall": ContextRecall(llm=judge),
        "answer_relevancy": AnswerRelevancy(llm=judge, embeddings=embeddings),
    }


def _score_sample(metrics: dict, question: str, answer: str, retrieved_contexts: list, reference: str) -> dict:
    return {
        "faithfulness": metrics["faithfulness"]
        .score(user_input=question, response=answer, retrieved_contexts=retrieved_contexts)
        .value,
        "context_precision": metrics["context_precision"]
        .score(user_input=question, reference=reference, retrieved_contexts=retrieved_contexts)
        .value,
        "context_recall": metrics["context_recall"]
        .score(user_input=question, retrieved_contexts=retrieved_contexts, reference=reference)
        .value,
        "answer_relevancy": metrics["answer_relevancy"].score(user_input=question, response=answer).value,
    }


def run_ragas_benchmark(store_name: str = VECTOR_DB_DIR, testset_size: int = 5, verbose: bool = True) -> dict:
    """
    Generate a synthetic evaluation set with RAGAS from the indexed fiscal code, run our
    RAG pipeline over it, and score it with RAGAS's Faithfulness, Context Precision,
    Context Recall and Answer Relevancy metrics.

    @return {"testset": DataFrame, "results": [...], "summary": {metric_name: avg_score}}
    """
    testset_df = generate_testset(store_name, testset_size)
    metrics = _build_ragas_metrics()

    results = []
    for _, row in testset_df.iterrows():
        outcome = answer_question(row["user_input"], store_name=store_name)
        retrieved_contexts = [c["text"] for c in outcome["citations"]]

        scores = _score_sample(metrics, row["user_input"], outcome["answer"], retrieved_contexts, row["reference"])
        results.append({"question": row["user_input"], "answer": outcome["answer"], **scores})

        if verbose:
            score_str = " ".join(f"{name}={scores[name]:.2f}" for name in METRIC_NAMES)
            print(f"{row['user_input'][:60]!r} -> {score_str}")

    summary = {name: sum(r[name] for r in results) / len(results) for name in METRIC_NAMES}
    if verbose:
        print("\nAverages:", {k: round(v, 3) for k, v in summary.items()})

    return {"testset": testset_df, "results": results, "summary": summary}


if __name__ == "__main__":
    run_ragas_benchmark()
